statement:
An equilateral triangle with side length `n` is cut into `n^2` unit equilateral triangles arranged in `n` rows, numbered from 1 at the top. Row `i` holds `2i - 1` unit triangles, named `(i, 1)` to `(i, 2i - 1)` from left to right. Odd positions point up and even positions point down, so the triangles that share a side with `(i, j)` are:

- `(i, j - 1)` and `(i, j + 1)` in the same row, when they exist;
- for an upward triangle (odd `j`), also `(i + 1, j + 1)` directly below it, when `i < n`;
- for a downward triangle (even `j`), also `(i - 1, j - 1)` directly above it.

All triangles start white. You paint some of them red, and then the following repeats: while some white triangle shares a side with at least two red triangles, one such triangle becomes red. Return a list of `[i, j]` coordinates of the triangles to paint at the start so that the process ends with every triangle red, using as few triangles as possible. Any valid list of the minimum size is accepted, in any order.

checker:
function check([n], actual, expected) {
  if (!Array.isArray(actual) || !Array.isArray(expected) || actual.length !== expected.length) return false;
  const id = (i, j) => (i - 1) * (i - 1) + j - 1;
  const red = new Uint8Array(n * n), count = new Uint8Array(n * n), queue = [];
  for (const cell of actual) {
    if (!Array.isArray(cell) || cell.length !== 2) return false;
    const [i, j] = cell;
    if (!Number.isInteger(i) || !Number.isInteger(j) || i < 1 || i > n || j < 1 || j > 2 * i - 1) return false;
    if (red[id(i, j)]) return false;
    red[id(i, j)] = 1;
    queue.push(i, j);
  }
  // Spread the red colour exactly as the statement describes and count the red triangles.
  let total = actual.length;
  for (let head = 0; head < queue.length; head += 2) {
    const i = queue[head], j = queue[head + 1], near = [];
    if (j > 1) near.push(i, j - 1);
    if (j < 2 * i - 1) near.push(i, j + 1);
    if (j % 2 === 1 && i < n) near.push(i + 1, j + 1);
    if (j % 2 === 0) near.push(i - 1, j - 1);
    for (let k = 0; k < near.length; k += 2) {
      const cell = id(near[k], near[k + 1]);
      if (red[cell]) continue;
      count[cell]++;
      if (count[cell] >= 2) {
        red[cell] = 1;
        total++;
        queue.push(near[k], near[k + 1]);
      }
    }
  }
  return total === n * n;
}

validator:
function validate([n]) {
  if (!Number.isInteger(n) || n < 1 || n > 1000) return 'n is a whole number from 1 to 1000.';
  return null;
}

