function colorRed(n) {
  const red = [[1, 1]];
  for (let row = n; row >= 2; row--) {
    const phase = (n - row) % 4;
    if (phase === 0) {
      for (let col = 1; col <= 2 * row - 1; col += 2) {
        red.push([row, col]);
      }
    } else if (phase === 1) {
      red.push([row, 2]);
    } else if (phase === 2) {
      for (let col = 3; col <= 2 * row - 1; col += 2) {
        red.push([row, col]);
      }
    } else {
      red.push([row, 1]);
    }
  }
  return red;
}

