function colorRed(n) {
  // The left-right mirror image of the four-row pattern, built from the top row down.
  const cells = [];
  for (let row = 1; row <= n; row++) {
    const last = 2 * row - 1;
    if (row === 1) {
      cells.push([1, 1]);
      continue;
    }
    switch ((n - row) % 4) {
      case 0:
        for (let col = last; col >= 1; col -= 2) cells.push([row, col]);
        break;
      case 1:
        cells.push([row, last - 1]);
        break;
      case 2:
        for (let col = last - 2; col >= 1; col -= 2) cells.push([row, col]);
        break;
      default:
        cells.push([row, last]);
    }
  }
  return cells;
}

