function generate(rand, size) {
  // Large answers hold about n^2 / 4 pairs, so large inputs stop near 200 to keep outputs within the app's limits.
  if (size === 'large') return [180 + Math.floor(rand() * 21)];
  return [1 + Math.floor(rand() * 12)];
}
